const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='kitchen-stock-v1',yen=n=>'¥'+Math.round(n).toLocaleString('ja-JP');
const seed=[['トマト','野菜','🍅',2,5,'kg',680,'青葉青果'],['玉ねぎ','野菜','🧅',12,5,'kg',240,'青葉青果'],['鶏もも肉','肉・魚','🍗',3,6,'kg',980,'ミートサービス'],['サーモン','肉・魚','🐟',0,3,'kg',2400,'築地水産'],['牛乳','乳製品','🥛',8,4,'本',260,'フードパートナー'],['卵','乳製品','🥚',30,20,'個',32,'フードパートナー'],['オリーブオイル','調味料','🫒',1,3,'本',1280,'フードパートナー'],['薄力粉','穀物','🌾',7,3,'kg',320,'フードパートナー'],['じゃがいも','野菜','🥔',9,5,'kg',280,'青葉青果'],['生クリーム','乳製品','🥛',2,4,'本',560,'フードパートナー']].map((a,i)=>({id:'i'+i,name:a[0],category:a[1],icon:a[2],stock:a[3],min:a[4],unit:a[5],price:a[6],supplier:a[7]}));
let db={items:seed,orders:[],history:[]},page='inventory',filter='すべて',search='';try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.items)&&Array.isArray(saved.orders)&&Array.isArray(saved.history))db=saved}catch(e){alert('保存済みデータを読み込めませんでした。サンプルを表示します。')}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(e){alert('保存に失敗しました。ブラウザの保存容量・設定を確認し、バックアップしてください。');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.opacity=0,2800)}
const low=()=>db.items.filter(i=>i.stock<=i.min), pending=()=>db.orders.filter(o=>o.status==='発注済み');
const status=i=>i.stock===0?'<span class="pill out">● 在庫なし</span>':i.stock<=i.min?'<span class="pill low">● 発注が必要</span>':'<span class="pill">● 適正在庫</span>';
function render(){const names={inventory:'在庫管理',orders:'発注管理',history:'入出庫履歴',suppliers:'仕入先'};$('#title').textContent=$('#breadcrumb').textContent=names[page];$('#subtitle').textContent={inventory:'食材のいまを把握して、仕込みにゆとりを。',orders:'必要な食材を、必要な分だけ。発注から入荷まで。',history:'食材の動きを、ひとつずつ記録。',suppliers:'いつもの仕入先と、食材をひと目で。'}[page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#orderBadge').textContent=pending().length||'';$('#add').textContent=page==='orders'?'＋ 発注を作成':'＋ 食材を登録';$('#stats').innerHTML=[['登録食材',db.items.length,'品目','すべての管理対象食材','▦'],['発注が必要',low().length,'品目','発注点以下の食材','↘'],['入荷待ち',pending().length,'件','発注済み・未入荷の発注','▤'],['在庫金額',yen(db.items.reduce((n,i)=>n+i.stock*i.price,0)),'','登録単価による概算','¥']].map((a,i)=>`<div class="stat ${i===1?'warn':''}"><label>${a[0]}</label><span class="symbol">${a[4]}</span><strong>${a[1]}<small>${a[2]}</small></strong><p>${a[3]}</p></div>`).join('');$('#alert').innerHTML=low().length?`<div class="notice"><span>◷</span><div><b>${low().length}品目の食材が発注点以下になっています</b><small>在庫を確認して、次の営業に備えましょう。</small></div><button id="suggest">まとめて発注を作成 →</button></div>`:'';$('#suggest')?.addEventListener('click',()=>orderModal(true));$('#toolbar').innerHTML=page==='inventory'?`<div class="filters"><h2>食材一覧 <span style="color:#a0a998;font-size:12px">${db.items.length}</span></h2><input id="search" placeholder="⌕ 食材名・仕入先で検索" aria-label="食材を検索" value="${esc(search)}"></div><div class="tabs">${['すべて','要発注','野菜','肉・魚','乳製品','その他'].map(t=>`<button class="${filter===t?'selected':''}" data-filter="${t}">${t}</button>`).join('')}</div>`:`<div class="filters"><h2>${names[page]}一覧</h2><span style="font-size:11px;color:#87937f">${page==='orders'?'CSVをダウンロードして仕入先に送付できます':''}</span></div>`;$('#search')?.addEventListener('input',e=>{search=e.target.value;renderRows()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});renderRows()}
function renderRows(){let html='';if(page==='inventory'){const items=db.items.filter(i=>(filter==='すべて'||filter==='要発注'&&i.stock<=i.min||filter===i.category||filter==='その他'&&!['野菜','肉・魚','乳製品'].includes(i.category))&&(i.name+i.supplier).includes(search));html=`<table><thead><tr><th>食材名</th><th>カテゴリー</th><th>現在庫</th><th>発注点</th><th>ステータス</th><th>仕入先</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><div class="food"><span class="foodicon">${i.icon||'◈'}</span><div><b>${esc(i.name)}</b><small>${yen(i.price)} / ${esc(i.unit)}</small></div></div></td><td>${esc(i.category)}</td><td><span class="num">${i.stock}</span> <span style="color:#8e9886;font-size:10px">${esc(i.unit)}</span><div class="bar"><i style="width:${Math.min(100,i.stock/Math.max(1,i.min*3)*100)}%;${i.stock<=i.min?'background:#d5ac65':''}"></i></div></td><td>${i.min} <small style="display:inline">${esc(i.unit)}</small></td><td>${status(i)}</td><td>${esc(i.supplier)}</td><td><button class="subtle" data-move="${i.id}">入出庫</button> <button class="subtle" data-edit="${i.id}" aria-label="${esc(i.name)}を編集">編集</button></td></tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty">該当する食材はありません。</div>'}<div class="tablefoot">${items.length} 品目を表示　・　在庫数が発注点以下になるとお知らせします</div>`}else if(page==='orders'){html=db.orders.slice().reverse().map(o=>`<div class="order"><div><h3>${esc(o.supplier)}　<span class="pill">${o.status}</span></h3><small>${o.date} · ${o.id.slice(0,8)}</small><p>${o.lines.map(l=>`${esc(l.name)} × ${l.qty} ${esc(l.unit)}`).join(' / ')}</p><b>${yen(o.lines.reduce((n,l)=>n+l.qty*l.price,0))}</b></div><div class="actions"><button data-csv="${o.id}">CSV出力</button>${o.status==='発注済み'?`<button class="primary" data-receive="${o.id}">入荷を記録</button>`:''}</div></div>`).join('')||'<div class="empty">まだ発注はありません。「発注を作成」から追加できます。</div>'}else if(page==='history'){html='<table><thead><tr><th>日時</th><th>食材</th><th>操作</th><th>数量</th><th>メモ</th></tr></thead><tbody>'+db.history.slice().reverse().map(h=>`<tr><td>${esc(h.date)}</td><td>${esc(h.name)}</td><td>${esc(h.type)}</td><td>${h.qty>0?'+':''}${h.qty} ${esc(h.unit)}</td><td>${esc(h.note)}</td></tr>`).join('')+'</tbody></table>';if(!db.history.length)html='<div class="empty">入出庫や入荷を記録すると、ここに履歴が表示されます。</div>'}else{html=[...new Set(db.items.map(i=>i.supplier))].map(s=>`<div class="order"><div><h3>⌂　${esc(s)}</h3><p>${db.items.filter(i=>i.supplier===s).map(i=>esc(i.name)).join(' ・ ')}</p></div><span class="pill">${db.items.filter(i=>i.supplier===s).length} 品目</span></div>`).join('')}$('#content').innerHTML=html;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>itemModal(b.dataset.edit));document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>moveModal(b.dataset.move));document.querySelectorAll('[data-receive]').forEach(b=>b.onclick=()=>receive(b.dataset.receive));document.querySelectorAll('[data-csv]').forEach(b=>b.onclick=()=>{const o=db.orders.find(o=>o.id===b.dataset.csv);csv(['発注日','仕入先','食材','数量','単位','単価','金額'],o.lines.map(l=>[o.date,o.supplier,l.name,l.qty,l.unit,l.price,l.qty*l.price]),'発注書')})}
function modal(title,fields,submit){$('#modalTitle').textContent=title;$('#fields').innerHTML=fields;$('#form').onsubmit=e=>{e.preventDefault();if(submit(new FormData(e.target))!==false){$('#dialog').close();persist();render()}};$('#dialog').showModal()}
const input=(label,name,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${type==='number'?'min="0" max="100000000" step="0.01"':''} ${type==='text'?'maxlength="100"':''}></label>`;
function itemModal(id){const i=db.items.find(i=>i.id===id);modal(i?'食材を編集':'食材を登録',input('食材名','name',i?.name||'')+`<label>カテゴリー<select name="category">${['野菜','肉・魚','乳製品','調味料','穀物','その他'].map(c=>`<option ${i?.category===c?'selected':''}>${c}</option>`).join('')}</select></label>`+(i?'':input('初期在庫','stock',0,'number'))+input('発注点','min',i?.min??3,'number')+input('単位（kg・本・個 など）','unit',i?.unit||'kg')+input('単価（円・税抜）','price',i?.price??0,'number')+input('仕入先名','supplier',i?.supplier||''),f=>{for(const k of ['name','unit','supplier'])if(!f.get(k).trim()){toast('空白だけの値は登録できません');return false}const v=Object.fromEntries(f);for(const k of ['stock','min','price'])if(k in v)v[k]=Number(v[k]);if(i)Object.assign(i,v);else db.items.push({...v,id:crypto.randomUUID(),icon:'◈'});toast('食材を保存しました')})}
function log(i,type,qty,note){db.history.push({date:new Date().toLocaleString('ja-JP'),name:i.name,unit:i.unit,type,qty,note})}
function moveModal(id){const i=db.items.find(i=>i.id===id);modal(i.name+' の入出庫',`<p>現在庫：<b>${i.stock} ${esc(i.unit)}</b></p><label>操作<select name="type"><option>出庫（使用）</option><option>入庫</option><option>廃棄</option><option>棚卸（実数に修正）</option></select></label>`+input('数量（'+i.unit+'）','qty','','number')+'<label>メモ<input name="note" maxlength="200" placeholder="仕込み・納品・棚卸など"></label>',f=>{const q=Number(f.get('qty')),t=f.get('type');const next=t.startsWith('棚卸')?q:t==='入庫'?i.stock+q:i.stock-q;if(next<0){toast('現在庫を超える数量は出庫できません');return false}const delta=Math.round((next-i.stock)*100)/100;i.stock=Math.round(next*100)/100;log(i,t,delta,f.get('note'));toast('在庫を更新しました')})}
function orderModal(auto=false){const candidates=auto?low():db.items;if(!candidates.length){toast('発注できる食材がありません');return}modal(auto?'不足食材から発注を作成':'発注を作成',`<p>仕入先ごとに発注を作成します。数量を0にした食材は含めません。作成後、CSVを仕入先へ送付してください。</p>`+candidates.map(i=>input(i.name+'（'+i.unit+'）',i.id,auto?Math.max(0,i.min*2-i.stock-pending().flatMap(o=>o.lines).filter(l=>l.id===i.id).reduce((s,l)=>s+l.qty,0)):0,'number')).join(''),f=>{const groups={};for(const i of candidates){const qty=Number(f.get(i.id));if(qty>0)(groups[i.supplier]??=[]).push({id:i.id,name:i.name,unit:i.unit,price:i.price,qty})}if(!Object.keys(groups).length){toast('1品目以上の数量を入力してください');return false}Object.entries(groups).forEach(([supplier,lines])=>db.orders.push({id:crypto.randomUUID(),date:new Date().toLocaleDateString('ja-JP'),supplier,lines,status:'発注済み'}));page='orders';toast('発注を作成しました。CSVを仕入先に送付してください')})}
function receive(id){const o=db.orders.find(o=>o.id===id);if(o.status!=='発注済み')return;modal('入荷を記録',`<p>${esc(o.supplier)}からの発注分をすべて入荷済みにし、在庫へ加算します。</p><p>${o.lines.map(l=>`${esc(l.name)}：${l.qty} ${esc(l.unit)}`).join('<br>')}</p>`,()=>{if(o.status!=='発注済み')return false;for(const l of o.lines){const i=db.items.find(i=>i.id===l.id);i.stock=Math.round((i.stock+l.qty)*100)/100;log(i,'発注から入荷',l.qty,o.supplier)}o.status='入荷済み';toast('入荷を記録し、在庫を更新しました')})}
function download(name,body,type){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(head,rows,name){const cell=x=>'"'+String(typeof x==='string'&&/^[=+@\-\t\r]/.test(x)?"'"+x:x).replaceAll('"','""')+'"';download(name+'.csv','\uFEFF'+[head,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
$('#export').onclick=()=>csv(['食材','カテゴリー','現在庫','単位','発注点','単価','仕入先'],db.items.map(i=>[i.name,i.category,i.stock,i.unit,i.min,i.price,i.supplier]),'在庫一覧');$('#backup').onclick=()=>download('kitchen-stock-backup.json',JSON.stringify(db,null,2),'application/json');$('#add').onclick=()=>page==='orders'?orderModal():itemModal();$('#close').onclick=$('#cancel').onclick=()=>$('#dialog').close();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$('#today').textContent=new Date().toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric',weekday:'short'});render();
